CREATE SCHEMA IF NOT EXISTS app;SET search_path TO app, public;CREATE TABLE pole (  id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,  background   VARCHAR(512));CREATE TABLE "user" (    id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,    pole_id      BIGINT REFERENCES pole(id) ON DELETE SET NULL,    is_admin     BOOLEAN NOT NULL DEFAULT FALSE,    username     VARCHAR(64) NOT NULL UNIQUE,    avatar       VARCHAR(2048),    email        VARCHAR(255) UNIQUE,    password     VARCHAR(255) NOT NULL,    name         VARCHAR(255),    status       VARCHAR(32),    tiktok       VARCHAR(255),    vk           VARCHAR(255),    telegram     VARCHAR(255));CREATE TABLE genus (   id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,   genus_name   VARCHAR(255) NOT NULL UNIQUE);CREATE TABLE plant (   id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,   genus_id            BIGINT NOT NULL REFERENCES genus(id) ON DELETE RESTRICT,   name                VARCHAR(255) NOT NULL,   image_url           VARCHAR(2048),   height              NUMERIC(10, 2) CHECK (height IS NULL OR height >= 0),   description         TEXT,   watering_frequency  VARCHAR(100),   temp_max            NUMERIC(5, 2),   temp_min            NUMERIC(5, 2),   sunlight            VARCHAR(100),   collection          VARCHAR(255),   preparation         TEXT,   storage             TEXT,   readiness_check     TEXT,   drying              TEXT,   CONSTRAINT chk_plant_temp       CHECK (temp_max IS NULL OR temp_min IS NULL OR temp_max >= temp_min));CREATE TABLE "comment" (   id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,   entity_id    BIGINT NOT NULL,   user_id      BIGINT NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,   parent_id    BIGINT REFERENCES "comment"(id) ON DELETE CASCADE,   entity_type  VARCHAR(32) NOT NULL,   content      TEXT NOT NULL,   created_at   TIMESTAMPTZ NOT NULL DEFAULT NOW(),   is_deleted   BOOLEAN NOT NULL DEFAULT FALSE);CREATE TABLE reaction (  user_id        BIGINT NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,  comment_id     BIGINT NOT NULL REFERENCES "comment"(id) ON DELETE CASCADE,  reaction_type  VARCHAR(32) NOT NULL,  PRIMARY KEY (user_id, comment_id));CREATE TABLE plant_pole (    plant_id  BIGINT NOT NULL REFERENCES plant(id) ON DELETE CASCADE,    pole_id   BIGINT NOT NULL REFERENCES pole(id) ON DELETE CASCADE,    x         NUMERIC(10, 2) NOT NULL DEFAULT 0,    y         NUMERIC(10, 2) NOT NULL DEFAULT 0,    size      NUMERIC(10, 2) NOT NULL DEFAULT 1 CHECK (size > 0),    rotate    NUMERIC(7, 2) NOT NULL DEFAULT 0,    PRIMARY KEY (plant_id, pole_id));CREATE TABLE tag (     id        BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,     name      VARCHAR(100) NOT NULL,     category  VARCHAR(50) NOT NULL,     CONSTRAINT uq_tag_name_category UNIQUE (name, category));CREATE TABLE plant_tag (   plant_id  BIGINT NOT NULL REFERENCES plant(id) ON DELETE CASCADE,   tag_id    BIGINT NOT NULL REFERENCES tag(id) ON DELETE CASCADE,   PRIMARY KEY (plant_id, tag_id));CREATE TABLE favorite (      user_id   BIGINT NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,      plant_id  BIGINT NOT NULL REFERENCES plant(id) ON DELETE CASCADE,      PRIMARY KEY (user_id, plant_id));CREATE TABLE recipe (    id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,    name         VARCHAR(255) NOT NULL,    additional   TEXT,    description  TEXT,    advice       TEXT,    recipe       TEXT NOT NULL,    healthy      BOOLEAN NOT NULL DEFAULT FALSE);CREATE TABLE recipe_plant (                              recipe_id  BIGINT NOT NULL REFERENCES recipe(id) ON DELETE CASCADE,                              plant_id   BIGINT NOT NULL REFERENCES plant(id) ON DELETE CASCADE,                              PRIMARY KEY (recipe_id, plant_id));-- Индексы по внешним ключам / частым выборкамCREATE INDEX idx_user_pole_id          ON "user"(pole_id);CREATE INDEX idx_plant_genus_id        ON plant(genus_id);CREATE INDEX idx_comment_user_id       ON "comment"(user_id);CREATE INDEX idx_comment_parent_id     ON "comment"(parent_id);CREATE INDEX idx_comment_entity        ON "comment"(entity_type, entity_id);CREATE INDEX idx_reaction_comment_id   ON reaction(comment_id);CREATE INDEX idx_plant_pole_pole_id    ON plant_pole(pole_id);CREATE INDEX idx_plant_tag_tag_id      ON plant_tag(tag_id);CREATE INDEX idx_favorite_plant_id     ON favorite(plant_id);CREATE INDEX idx_recipe_plant_plant_id ON recipe_plant(plant_id);